<?php
namespace App\Services;
use App\Modules\Operations\Models\Assignment; use App\Modules\Tasks\Models\{Checklist,ChecklistExecution,TaskExecution}; use Illuminate\Database\QueryException; use Illuminate\Support\Carbon;
class DailyTaskService { public function materialize(Assignment $assignment): void { $date=$assignment->date->toDateString(); Checklist::query()->whereHas('shifts', fn ($shifts) => $shifts->whereKey($assignment->shift_id))->where('status','active')->with('items.task')->each(function (Checklist $checklist) use ($assignment,$date) { $identity=['checklist_id'=>$checklist->id,'core_user_id'=>$assignment->core_user_id,'assignment_id'=>$assignment->id,'execution_date'=>$date]; try { $execution=ChecklistExecution::firstOrCreate($identity); } catch (QueryException $exception) { if (!str_contains(strtolower($exception->getMessage()),'checklist_execution_assignment_unique')) throw $exception; $execution=ChecklistExecution::query()->where($identity)->firstOrFail(); } foreach($checklist->items as $item) { TaskExecution::firstOrCreate(['checklist_execution_id'=>$execution->id,'checklist_item_id'=>$item->id],['core_user_id'=>$assignment->core_user_id,'branch_id'=>$assignment->branch_id,'assignment_id'=>$assignment->id,'scheduled_date'=>$date,'scheduled_start'=>$item->start_time,'scheduled_end'=>$item->due_time,'task_name_snapshot'=>$item->task->name,'checklist_name_snapshot'=>$checklist->name]); } }); } }
